CREATE OR REPLACE FUNCTION fun_login_usuario(
    p_email     tab_Usuarios.correo_usuario%TYPE,
    p_password  TEXT
) RETURNS TABLE (
    status     TEXT,
    message    TEXT,
    ret_id_usuario tab_Usuarios.id_usuario%TYPE,
    ret_nombre     tab_Usuarios.nom_usuario%TYPE,
    ret_email      tab_Usuarios.correo_usuario%TYPE,
    ret_telefono   tab_Usuarios.num_telefono_usuario%TYPE,
    ret_direccion  tab_Usuarios.direccion_principal%TYPE,
    ret_token      TEXT
) AS $$
DECLARE
    v_usuario        RECORD;
    v_hash           tab_Usuarios.contra%TYPE;
    v_token          TEXT;
    v_intentos       tab_Usuarios.intentos_fallidos%TYPE;
    -- Variables de retorno con tipos de la tabla
    v_ret_id         tab_Usuarios.id_usuario%TYPE;
    v_ret_nombre     tab_Usuarios.nom_usuario%TYPE;
    v_ret_email      tab_Usuarios.correo_usuario%TYPE;
    v_ret_telefono   tab_Usuarios.num_telefono_usuario%TYPE;
    v_ret_direccion  tab_Usuarios.direccion_principal%TYPE;
BEGIN
    -- Buscar por correo (case-insensitive)
    SELECT u.* INTO v_usuario
      FROM tab_Usuarios u
     WHERE LOWER(u.correo_usuario) = LOWER(p_email);

    IF NOT FOUND THEN
        status := 'ERROR';
        message := 'Credenciales inválidas';
        ret_id_usuario := NULL;
        ret_nombre := NULL;
        ret_email := NULL;
        ret_telefono := NULL;
        ret_direccion := NULL;
        ret_token := NULL;
        RETURN NEXT;
        RETURN;
    END IF;

    IF NOT v_usuario.activo THEN
        status := 'ERROR';
        message := 'Usuario inactivo. Contacte al administrador';
        ret_id_usuario := NULL;
        ret_nombre := NULL;
        ret_email := NULL;
        ret_telefono := NULL;
        ret_direccion := NULL;
        ret_token := NULL;
        RETURN NEXT;
        RETURN;
    END IF;

    IF v_usuario.bloqueado THEN
        status := 'ERROR';
        message := 'Usuario bloqueado por múltiples intentos fallidos';
        ret_id_usuario := NULL;
        ret_nombre := NULL;
        ret_email := NULL;
        ret_telefono := NULL;
        ret_direccion := NULL;
        ret_token := NULL;
        RETURN NEXT;
        RETURN;
    END IF;

    -- Verificar contraseña (DESACTIVADO EN SQL, SE HACE EN PHP)
    -- v_hash := MD5(p_password || v_usuario.salt);

    -- Éxito parcial: Encontramos el usuario, devolvemos data para que PHP verifique
    v_ret_id := v_usuario.id_usuario;
    v_ret_nombre := v_usuario.nom_usuario;
    v_ret_email := v_usuario.correo_usuario;
    v_ret_telefono := v_usuario.num_telefono_usuario;
    v_ret_direccion := COALESCE(v_usuario.direccion_principal, '');
    v_token := MD5(v_usuario.id_usuario::text || v_usuario.correo_usuario || clock_timestamp()::text);

    -- Retornar valores (status SUCCESS aquí solo significa 'Usuario Encontrado')
    status := 'SUCCESS';
    message := 'Usuario encontrado';
    ret_id_usuario := v_ret_id;
    ret_nombre := v_ret_nombre;
    ret_email := v_ret_email;
    ret_telefono := v_ret_telefono;
    ret_direccion := v_ret_direccion;
    ret_token := v_usuario.contra; -- DEVOLVEMOS EL HASH EN ESTE CAMPO PARA PHP
    RETURN NEXT;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION fun_set_rol_usuario(
    p_id_usuario tab_Usuarios.id_usuario%TYPE,
    p_rol        tab_Usuarios.rol%TYPE
) RETURNS TABLE (
    status  TEXT,
    message TEXT
) AS $$
DECLARE
    v_exist BOOLEAN;
BEGIN
    -- Verificar si el usuario existe
    SELECT EXISTS(
        SELECT 1 FROM tab_Usuarios WHERE id_usuario = p_id_usuario
    ) INTO v_exist;

    IF NOT v_exist THEN
        RETURN QUERY SELECT 
            'ERROR'::TEXT,
            'Usuario no encontrado'::TEXT;
        RETURN;
    END IF;

    -- Actualizar rol
    UPDATE tab_Usuarios
       SET rol = p_rol,
           usr_update = CURRENT_USER,
           fec_update = CURRENT_TIMESTAMP
     WHERE id_usuario = p_id_usuario;

    RETURN QUERY SELECT
        'SUCCESS'::TEXT,
        'Rol actualizado correctamente'::TEXT;

END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION fun_update_usuario(
    Kid_usuario             tab_Usuarios.id_usuario%TYPE,
    Knom_usuario            tab_Usuarios.nom_usuario%TYPE,
    Kcorreo_usuario         tab_Usuarios.correo_usuario%TYPE,
    Knum_telefono_usuario   tab_Usuarios.num_telefono_usuario%TYPE,
    Kdireccion_principal    tab_Usuarios.direccion_principal%TYPE,
    Kactivo                 tab_Usuarios.activo%TYPE
) RETURNS BOOLEAN AS
$$
BEGIN
    UPDATE tab_Usuarios SET
        nom_usuario = Knom_usuario,
        correo_usuario = Kcorreo_usuario,
        num_telefono_usuario = Knum_telefono_usuario,
        direccion_principal = Kdireccion_principal,
        activo = Kactivo
    WHERE id_usuario = Kid_usuario;

    -- Verifica si alguna fila fue afectada por la operación UPDATE
    IF FOUND THEN
        RETURN TRUE; -- El usuario fue encontrado y actualizado
    ELSE
        RETURN FALSE; -- El usuario no fue encontrado, no se realizó ninguna actualización
    END IF;
END;
$$
LANGUAGE PLPGSQL;


-- Función para actualizar un producto en tab_Productos

CREATE OR REPLACE FUNCTION fun_insert_usuarios(
    wid_usuario tab_Usuarios.id_usuario%TYPE,
    wnom_usuario tab_Usuarios.nom_usuario%TYPE,
    wcorreo_usuario tab_Usuarios.correo_usuario%TYPE,
    wnum_telefono_usuario tab_Usuarios.num_telefono_usuario%TYPE,
    wdireccion_principal tab_Usuarios.direccion_principal%TYPE DEFAULT NULL
) RETURNS TEXT AS
$BODY$
    DECLARE wusuario tab_Usuarios.id_usuario%TYPE;
    BEGIN
        -- Verificar si ya existe un usuario con el mismo ID o correo
        SELECT id_usuario INTO wusuario FROM tab_Usuarios
        WHERE id_usuario = wid_usuario OR correo_usuario = wcorreo_usuario;
        
        IF FOUND THEN
            RETURN 'ERROR: Usuario ya existe con ese ID o correo electrónico';
        ELSE
            BEGIN
                INSERT INTO tab_Usuarios (id_usuario, nom_usuario, correo_usuario, num_telefono_usuario, direccion_principal, activo)
                VALUES (wid_usuario, wnom_usuario, wcorreo_usuario, wnum_telefono_usuario, wdireccion_principal, TRUE);
                
                RETURN 'SUCCESS: Usuario insertado correctamente con ID ' || wid_usuario;
            EXCEPTION
                WHEN OTHERS THEN
                    RETURN 'ERROR: ' || SQLERRM;
            END;
        END IF;
    END;
$BODY$
LANGUAGE PLPGSQL;

-- UPDATE - Actualizar usuario

CREATE OR REPLACE FUNCTION fun_update_usuarios(
    wid_usuario tab_Usuarios.id_usuario%TYPE,
    wnom_usuario tab_Usuarios.nom_usuario%TYPE,
    wcorreo_usuario tab_Usuarios.correo_usuario%TYPE,
    wnum_telefono_usuario tab_Usuarios.num_telefono_usuario%TYPE,
    wdireccion_principal tab_Usuarios.direccion_principal%TYPE DEFAULT NULL
) RETURNS TEXT AS
$BODY$
    DECLARE 
        wcorreo_existente tab_Usuarios.id_usuario%TYPE;
    BEGIN
        -- Verificar si el nuevo correo ya existe en otro usuario
        SELECT id_usuario INTO wcorreo_existente FROM tab_Usuarios
        WHERE correo_usuario = wcorreo_usuario AND id_usuario != wid_usuario;
        
        IF FOUND THEN
            RETURN 'ERROR: El correo electrónico ya está registrado en otro usuario';
        END IF;
        
        -- Realizar la actualización
        UPDATE tab_Usuarios SET 
            nom_usuario = wnom_usuario,
            correo_usuario = wcorreo_usuario,
            num_telefono_usuario = wnum_telefono_usuario,
            direccion_principal = wdireccion_principal
        WHERE id_usuario = wid_usuario;
        
        IF FOUND THEN
            RETURN 'SUCCESS: Usuario actualizado correctamente';
        ELSE
            RETURN 'ERROR: No se encontró el usuario con ID ' || wid_usuario;
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            RETURN 'ERROR: ' || SQLERRM;
    END;
$BODY$
LANGUAGE PLPGSQL;

-- DELETE - Eliminar usuario (soft delete)

CREATE OR REPLACE FUNCTION fun_delete_usuarios(
    wid_usuario tab_Usuarios.id_usuario%TYPE
) RETURNS TEXT AS
$BODY$
    BEGIN
        UPDATE tab_Usuarios SET activo = FALSE WHERE id_usuario = wid_usuario;
        IF FOUND THEN
            RETURN 'SUCCESS: Usuario desactivado correctamente';
        ELSE
            RETURN 'ERROR: No se encontró el usuario con ID ' || wid_usuario;
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            RETURN 'ERROR: ' || SQLERRM;
    END;
$BODY$
LANGUAGE PLPGSQL;

